     * The machine id `M`, 43 characters.
     */
    fun `machineKey`(): kotlin.String
    
    /**
     * Hardware model, when known.
     */
    fun `model`(): kotlin.String?
    
    /**
     * `user@full-hostname`.
     */
    fun `name`(): kotlin.String
    
    /**
     * OS name and version; empty when the link has none.
     */
    fun `os`(): kotlin.String
    
