    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithHandle(block: (handle: Long) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the handle being freed concurrently.
        try {
            return block(this.uniffiCloneHandle())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_sealctl_core_fn_free_words(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_sealctl_core_fn_clone_words(handle, status)
        }
    }

    
    /**
     * The 32 bytes of entropy, for the words backup item only.
     */override fun `entropy`(): kotlin.ByteArray {
            return FfiConverterByteArray.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_sealctl_core_fn_method_words_entropy(
        it,
        _status)
}
    }
    )
    }
    

    
    /**
     * The 24 words in order, for the protected view only.
     */override fun `list`(): List<kotlin.String> {
            return FfiConverterSequenceString.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_sealctl_core_fn_method_words_list(
        it,
        _status)
}
    }
    )
    }
    

    

    


    
    companion object {
        
    /**
     * The words for 32 bytes of entropy (the words backup item holds these).
     */
    @Throws(CoreException::class) fun `fromEntropy`(`bytes`: kotlin.ByteArray): Words {
            return FfiConverterTypeWords.lift(
    uniffiRustCallWithError(CoreException) { _status ->
    UniffiLib.uniffi_sealctl_core_fn_constructor_words_from_entropy(
    
        
        FfiConverterByteArray.lower(`bytes`),_status)
}
    )
    }
    

        
    /**
     * 24 new words from the OS random source.
     */
    @Throws(CoreException::class) fun `generate`(): Words {
            return FfiConverterTypeWords.lift(
    uniffiRustCallWithError(CoreException) { _status ->
    UniffiLib.uniffi_sealctl_core_fn_constructor_words_generate(
    
        _status)
}
    )
    }
    

        
    /**
     * Parses 24 typed words. Case and surrounding spaces are ignored; a word may be given by
     * its first four letters (or more) when they name exactly one word, as on the card.
     */
    @Throws(CoreException::class) fun `parse`(`list`: List<kotlin.String>): Words {
            return FfiConverterTypeWords.lift(
    uniffiRustCallWithError(CoreException) { _status ->
    UniffiLib.uniffi_sealctl_core_fn_constructor_words_parse(
    
        
        FfiConverterSequenceString.lower(`list`),_status)
}
    )
    }
    

        
    }
    
}


/**
 * @suppress
 */
public object FfiConverterTypeWords: FfiConverter<Words, Long> {
    override fun lower(value: Words): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): Words {
        return Words(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): Words {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: Words) = 8UL

    override fun write(value: Words, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



