/**
 * Every failure the core reports, to Rust callers and through UniFFI.
 */
sealed class CoreException: kotlin.Exception() {
    
    /**
     * Word number `index` (from 0) is not a BIP39 English word.
     */
    class UnknownWord(
        
        /**
         * Position of the word, from 0.
         */
        val `index`: kotlin.UInt
        ) : CoreException() {
        override val message
            get() = "index=${ `index` }"
    }
    
    /**
     * The words are all on the list but their BIP39 checksum fails.
     */
    class Checksum(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    /**
     * Not 24 words.
     */
    class Count(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    /**
     * Not a sealctl pairing link or code.
     */
    class BadLink(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    /**
     * A pairing code past its expiry, or a request outside the 10-minute window.
     */
    class Expired(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    /**
     * The other side speaks a newer protocol version.
     */
    class NewerVersion(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    /**
     * A pairing or move proof that does not check out.
     */
    class BadProof(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    /**
     * An Ed25519 signature that does not verify.
     */
    class BadSignature(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    /**
     * A sealed string or blob that cannot be decoded or opened, or is too long.
     */
    class BadSealed(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    /**
     * This request was already answered.
     */
    class Replay(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    /**
     * A key purpose or object id outside the allowed set.
     */
    class BadLabel(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    /**
     * A plan that breaks the plan rules or does not match its hash.
     */
    class BadPlan(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    /**
     * Bytes or text that are not a valid key (wrong length or encoding).
     */
    class BadKey(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    /**
     * The answer does not fit the request's kind (for example keys for a `report`).
     */
    class WrongDecision(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    /**
     * The body does not fit in its sealed form (4,096 characters, state blob 1 MiB).
     */
    class TooLarge(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    /**
     * A failure that should not happen (the OS random source, an encoder).
     */
    class Internal(
        ) : CoreException() {
        override val message
            get() = ""
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): CoreException = FfiConverterTypeCoreError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeCoreError : FfiConverterRustBuffer<CoreException> {
    override fun read(buf: ByteBuffer): CoreException {
        

        return when(buf.getInt()) {
            1 -> CoreException.UnknownWord(
                FfiConverterUInt.read(buf),
                )
            2 -> CoreException.Checksum()
            3 -> CoreException.Count()
            4 -> CoreException.BadLink()
            5 -> CoreException.Expired()
            6 -> CoreException.NewerVersion()
            7 -> CoreException.BadProof()
            8 -> CoreException.BadSignature()
            9 -> CoreException.BadSealed()
            10 -> CoreException.Replay()
            11 -> CoreException.BadLabel()
            12 -> CoreException.BadPlan()
            13 -> CoreException.BadKey()
            14 -> CoreException.WrongDecision()
            15 -> CoreException.TooLarge()
            16 -> CoreException.Internal()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CoreException): ULong {
        return when(value) {
            is CoreException.UnknownWord -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUInt.allocationSize(value.`index`)
            )
            is CoreException.Checksum -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.Count -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.BadLink -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.Expired -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.NewerVersion -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.BadProof -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.BadSignature -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.BadSealed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.Replay -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.BadLabel -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.BadPlan -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.BadKey -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.WrongDecision -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.TooLarge -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.Internal -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: CoreException, buf: ByteBuffer) {
        when(value) {
            is CoreException.UnknownWord -> {
                buf.putInt(1)
                FfiConverterUInt.write(value.`index`, buf)
                Unit
            }
            is CoreException.Checksum -> {
                buf.putInt(2)
                Unit
            }
            is CoreException.Count -> {
                buf.putInt(3)
                Unit
            }
            is CoreException.BadLink -> {
                buf.putInt(4)
                Unit
            }
            is CoreException.Expired -> {
                buf.putInt(5)
                Unit
            }
            is CoreException.NewerVersion -> {
                buf.putInt(6)
                Unit
            }
            is CoreException.BadProof -> {
                buf.putInt(7)
                Unit
            }
            is CoreException.BadSignature -> {
                buf.putInt(8)
                Unit
            }
            is CoreException.BadSealed -> {
                buf.putInt(9)
                Unit
            }
            is CoreException.Replay -> {
                buf.putInt(10)
                Unit
            }
            is CoreException.BadLabel -> {
                buf.putInt(11)
                Unit
            }
            is CoreException.BadPlan -> {
                buf.putInt(12)
                Unit
            }
            is CoreException.BadKey -> {
                buf.putInt(13)
                Unit
            }
            is CoreException.WrongDecision -> {
                buf.putInt(14)
                Unit
            }
            is CoreException.TooLarge -> {
                buf.putInt(15)
                Unit
            }
            is CoreException.Internal -> {
                buf.putInt(16)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * What the person (or the levels of asking) decided.
 */
sealed class Decision {
    
    /**
     * Declined (`declined`).
     */
    object Deny : Decision()
    
    
    /**
     * Refused for a reason.
     */
    data class Refuse(
        /**
         * The reason.
         */
        val `err`: com.sealctl.core.RefuseReason) : Decision()
        
    {
        

        companion object
    }
    
    /**
     * Keys and uses for the command that asked, then wiped (`grant: once`).
     */
    data class Once(
        /**
         * Where the phone is.
         */
        val `place`: com.sealctl.core.Place) : Decision()
        
    {
        

        companion object
    }
    
    /**
     * Kept until the session locks (`grant: session`).
     */
    data class Session(
        /**
         * Where the phone is.
         */
        val `place`: com.sealctl.core.Place) : Decision()
        
    {
        

        companion object
    }
    
    /**
     * `Session`, and the agent uses are remembered (`remember: true`).
     */
    data class Remember(
        /**
         * Where the phone is.
         */
        val `place`: com.sealctl.core.Place) : Decision()
        
    {
        

        companion object
    }
    
    /**
     * `unseal`: sign the plan and hand out keys named by it (`grant: plan`).
     */
    data class Plan(
        /**
         * Where the phone is.
         */
        val `place`: com.sealctl.core.Place, 
        /**
         * Approval time, or one hour later away from a trusted place; Unix ms.
         */
        val `notBefore`: kotlin.ULong) : Decision()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeDecision : FfiConverterRustBuffer<Decision>{
    override fun read(buf: ByteBuffer): Decision {
        return when(buf.getInt()) {
            1 -> Decision.Deny
            2 -> Decision.Refuse(
                FfiConverterTypeRefuseReason.read(buf),
                )
            3 -> Decision.Once(
                FfiConverterTypePlace.read(buf),
                )
            4 -> Decision.Session(
                FfiConverterTypePlace.read(buf),
                )
            5 -> Decision.Remember(
                FfiConverterTypePlace.read(buf),
                )
            6 -> Decision.Plan(
                FfiConverterTypePlace.read(buf),
                FfiConverterULong.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: Decision): ULong = when(value) {
        is Decision.Deny -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is Decision.Refuse -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeRefuseReason.allocationSize(value.`err`)
            )
        }
        is Decision.Once -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypePlace.allocationSize(value.`place`)
            )
        }
        is Decision.Session -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypePlace.allocationSize(value.`place`)
            )
        }
        is Decision.Remember -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypePlace.allocationSize(value.`place`)
            )
        }
        is Decision.Plan -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypePlace.allocationSize(value.`place`)
                + FfiConverterULong.allocationSize(value.`notBefore`)
            )
        }
    }

    override fun write(value: Decision, buf: ByteBuffer) {
        when(value) {
            is Decision.Deny -> {
                buf.putInt(1)
                Unit
            }
            is Decision.Refuse -> {
                buf.putInt(2)
                FfiConverterTypeRefuseReason.write(value.`err`, buf)
                Unit
            }
            is Decision.Once -> {
                buf.putInt(3)
                FfiConverterTypePlace.write(value.`place`, buf)
                Unit
            }
            is Decision.Session -> {
                buf.putInt(4)
                FfiConverterTypePlace.write(value.`place`, buf)
                Unit
            }
            is Decision.Remember -> {
                buf.putInt(5)
                FfiConverterTypePlace.write(value.`place`, buf)
                Unit
            }
            is Decision.Plan -> {
                buf.putInt(6)
                FfiConverterTypePlace.write(value.`place`, buf)
                FfiConverterULong.write(value.`notBefore`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





/**
 * The kinds of machine message (`type`).
 */
sealed class MessageKind {
    
    /**
     * Lock the session.
     */
    data class Lock(
        /**
         * `phone`, `place` or `words`.
         */
        val `reason`: kotlin.String) : MessageKind()
        
    {
        

        companion object
    }
    
    /**
     * This machine's remembered answers.
     */
    data class Answers(
        /**
         * At most 40 per message.
         */
        val `answers`: List<com.sealctl.core.Answer>, 
        /**
         * Another `answers` message follows.
         */
        val `more`: kotlin.Boolean) : MessageKind()
        
    {
        

        companion object
    }
    
    /**
     * The status `seq` the phone stored.
     */
    data class Ack(
        /**
         * The `seq`.
         */
        val `ack`: kotlin.ULong) : MessageKind()
        
    {
        

        companion object
    }
    
    /**
     * A level 3 action, for the machine to show.
     */
    data class Notice(
        /**
         * What happened.
         */
        val `notice`: com.sealctl.core.Notice) : MessageKind()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeMessageKind : FfiConverterRustBuffer<MessageKind>{
    override fun read(buf: ByteBuffer): MessageKind {
        return when(buf.getInt()) {
            1 -> MessageKind.Lock(
                FfiConverterString.read(buf),
                )
            2 -> MessageKind.Answers(
                FfiConverterSequenceTypeAnswer.read(buf),
                FfiConverterBoolean.read(buf),
                )
            3 -> MessageKind.Ack(
                FfiConverterULong.read(buf),
                )
            4 -> MessageKind.Notice(
                FfiConverterTypeNotice.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: MessageKind): ULong = when(value) {
        is MessageKind.Lock -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
        is MessageKind.Answers -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceTypeAnswer.allocationSize(value.`answers`)
                + FfiConverterBoolean.allocationSize(value.`more`)
            )
        }
        is MessageKind.Ack -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`ack`)
            )
        }
        is MessageKind.Notice -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeNotice.allocationSize(value.`notice`)
            )
        }
    }

    override fun write(value: MessageKind, buf: ByteBuffer) {
        when(value) {
            is MessageKind.Lock -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is MessageKind.Answers -> {
                buf.putInt(2)
                FfiConverterSequenceTypeAnswer.write(value.`answers`, buf)
                FfiConverterBoolean.write(value.`more`, buf)
                Unit
            }
            is MessageKind.Ack -> {
                buf.putInt(3)
                FfiConverterULong.write(value.`ack`, buf)
                Unit
            }
            is MessageKind.Notice -> {
                buf.putInt(4)
                FfiConverterTypeNotice.write(value.`notice`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





/**
 * Where the phone is when it approves; sets the machine's allowance.
 */

enum class Place {
    
    /**
     * Inside a trusted place.
     */
    TRUSTED,
    /**
     * Places are on and the phone is elsewhere.
     */
    OTHER,
    /**
